const page="<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <meta name=\"theme-color\" content=\"#091019\" />\n  <meta name=\"description\" content=\"An English-only fluency gym for fast, natural American speech.\" />\n  <title>Jack: American Mode</title>\n  <link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='14' fill='%23091019'/%3E%3Cpath d='M18 44V20h9v16h12V20h9v24z' fill='%23ff6b35'/%3E%3C/svg%3E\" />\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n  <link href=\"https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\" />\n  <style>:root {\n  --ink:#091019;\n  --ink-2:#111b27;\n  --panel:#142130;\n  --line:#2a3848;\n  --paper:#edf1f3;\n  --muted:#92a0ad;\n  --accent:#ff6b35;\n  --acid:#d4ff4f;\n  --white:#fff;\n}\n*{box-sizing:border-box}\nhtml{font-size:16px;background:var(--ink)}\nbody{margin:0;background:var(--ink);color:var(--paper);font-family:Manrope,system-ui,sans-serif;min-height:100vh}\nbutton,textarea{font:inherit}\nbutton{cursor:pointer}\n.shell{display:grid;grid-template-columns:250px 1fr;min-height:100vh}\n.rail{position:fixed;inset:0 auto 0 0;width:250px;padding:28px 22px;border-right:1px solid var(--line);display:flex;flex-direction:column;background:#0b131d;z-index:4}\n.brand{display:flex;gap:12px;align-items:center;padding:0 6px 30px}\n.brand-mark{width:42px;height:42px;display:grid;place-items:center;background:var(--accent);color:var(--ink);font-weight:800;font-size:.86rem;letter-spacing:-.04em}\n.brand strong{display:block;font-size:.88rem;letter-spacing:.2em}\n.brand span{display:block;color:var(--muted);font:500 .62rem/1.5 DM Mono,monospace;letter-spacing:.13em;margin-top:2px}\n.mode-nav{display:grid;gap:8px}\n.nav-item{width:100%;display:grid;grid-template-columns:34px 1fr;gap:8px;text-align:left;align-items:start;padding:15px 12px;border:1px solid transparent;background:transparent;color:var(--muted);transition:.2s}\n.nav-item span{font:500 .69rem DM Mono;color:#5f7081}\n.nav-item b{font-size:.82rem;line-height:1.35;letter-spacing:.03em}\n.nav-item:hover{color:var(--white);border-color:var(--line)}\n.nav-item.active{background:var(--panel);color:var(--white);border-color:#34475a}\n.nav-item.active span{color:var(--accent)}\n.rail-bottom{margin-top:auto;display:grid;gap:26px;padding:0 6px}\n.streak{display:flex;gap:10px;align-items:center;font:500 .58rem/1.15 DM Mono;color:var(--muted);letter-spacing:.12em}\n.streak-num{font:800 2.1rem Manrope;color:var(--acid);letter-spacing:-.08em}\n.level span{font:500 .58rem DM Mono;color:var(--muted);letter-spacing:.12em}\n.level strong{display:block;font-size:.82rem;margin:7px 0}\n.level-track{height:3px;background:var(--line)}\n.level-track i{display:block;width:62%;height:100%;background:var(--accent)}\nmain{grid-column:2;min-width:0}\n.topbar{height:74px;padding:0 clamp(22px,4vw,64px);display:flex;align-items:center;border-bottom:1px solid var(--line);font:500 .68rem DM Mono;letter-spacing:.12em;color:var(--muted)}\n.status{color:var(--paper)}\n.status i{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--acid);box-shadow:0 0 0 4px #d4ff4f1a;margin-right:9px}\n.date{margin-left:auto;margin-right:28px}\n.icon-button{border:0;background:transparent;color:var(--muted);font:500 .67rem DM Mono;letter-spacing:.1em;padding:8px}\n.workspace{display:none;width:min(1080px,calc(100% - 64px));margin:0 auto;padding:54px 0 80px}\n.workspace.active{display:block;animation:rise .35s ease-out}\n@keyframes rise{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}\n.session-head{display:flex;align-items:end;justify-content:space-between;margin-bottom:30px}\n.eyebrow,.card-label{font:500 .67rem DM Mono;color:var(--accent);letter-spacing:.15em}\nh1{font-size:clamp(2.4rem,5vw,4.8rem);letter-spacing:-.06em;line-height:.92;margin:12px 0 0;font-weight:700}\n.session-count{display:flex;align-items:baseline;font-family:DM Mono}\n.session-count strong{font-size:2rem;color:var(--paper)}\n.session-count span{font-size:.8rem;color:var(--muted)}\n.scenario-card,.rewrite-card{position:relative;background:var(--paper);color:var(--ink);padding:30px clamp(24px,4vw,52px) 34px;border-left:6px solid var(--accent)}\n.scenario-card:after,.rewrite-card:after{content:\"\";position:absolute;right:20px;top:20px;width:38px;height:38px;border-top:1px solid #a9b1b7;border-right:1px solid #a9b1b7}\n.scenario-meta{display:flex;justify-content:space-between;font:500 .67rem DM Mono;letter-spacing:.12em;color:#62717c}\n.difficulty{color:#bd3d14}\n.role{font-size:.83rem;color:#65717b;margin:30px 0 8px}\nblockquote{margin:0;max-width:820px;font-size:clamp(1.35rem,2.6vw,2.15rem);line-height:1.28;letter-spacing:-.035em;font-weight:650}\n.listen-button{border:0;background:transparent;color:#34404a;font:600 .66rem DM Mono;letter-spacing:.1em;padding:20px 0 0}\n.listen-button span{color:var(--accent);margin-right:8px}\n.prompt-audio{display:block;margin:0 0 0 auto;padding:14px 0}\n.conversation-log{display:grid;gap:10px;padding:18px 0 0}\n.chat-line{max-width:78%;padding:14px 17px;border:1px solid var(--line);font-size:.9rem;line-height:1.5}\n.chat-line span{display:block;font:500 .58rem DM Mono;letter-spacing:.12em;color:var(--muted);margin-bottom:6px}\n.chat-line.coach{background:var(--panel)}\n.chat-line.you{margin-left:auto;background:#1b2937;border-color:#435365}\n.chat-line.you span{color:var(--acid)}\n.response-zone{display:grid;grid-template-columns:1fr 2fr 1fr;align-items:center;min-height:220px;border:1px solid var(--line);border-top:0;background:linear-gradient(90deg,#0c151f,#101d29 50%,#0c151f)}\n.timer-wrap{padding-left:32px;display:flex;flex-direction:column;gap:7px}\n.timer-wrap span:last-child,.target span{font:500 .58rem DM Mono;color:var(--muted);letter-spacing:.13em}\n.timer{font:500 1.5rem DM Mono!important;color:var(--paper)!important;letter-spacing:-.06em!important}\n.record-core{text-align:center;display:flex;flex-direction:column;align-items:center}\n.record-button{width:76px;height:76px;border-radius:50%;border:1px solid #52606e;background:transparent;display:grid;place-items:center;transition:.2s;box-shadow:0 0 0 0 #ff6b3529}\n.record-button span{width:25px;height:25px;border-radius:50%;background:var(--accent)}\n.record-button:hover{border-color:var(--accent);transform:scale(1.03)}\n.record-button.recording{animation:pulse 1.4s infinite;border-color:var(--accent)}\n.record-button.recording span{border-radius:3px;width:20px;height:20px}\n@keyframes pulse{50%{box-shadow:0 0 0 16px #ff6b3500}0%{box-shadow:0 0 0 2px #ff6b3540}}\n.record-core strong{font:600 .72rem DM Mono;letter-spacing:.12em;margin-top:17px}\n.record-core small{color:var(--muted);font-size:.72rem;margin-top:6px}\n.target{text-align:right;padding-right:32px;display:flex;flex-direction:column;gap:7px}\n.target strong{font:600 .9rem DM Mono;color:var(--acid)}\n.transcript-wrap,.rewrite-input{margin-top:22px;border:1px solid var(--line);padding:24px;background:var(--ink-2)}\nlabel{display:block;font:500 .65rem DM Mono;color:var(--muted);letter-spacing:.13em;margin-bottom:12px}\ntextarea{display:block;width:100%;min-height:110px;resize:vertical;border:0;border-bottom:1px solid #405064;background:transparent;color:var(--paper);font-size:1.06rem;line-height:1.55;padding:5px 0 15px;outline:none}\ntextarea:focus{border-color:var(--accent)}\ntextarea::placeholder{color:#617080}\n.primary{border:0;background:var(--accent);color:var(--ink);font:700 .7rem DM Mono;letter-spacing:.1em;padding:15px 18px;margin-top:18px}\n.primary span{font-size:1rem;margin-left:12px}\n.primary:hover{background:#ff8054}\n.wide{width:100%;margin-top:18px}\n.hidden{display:none!important}\n.results{margin-top:22px;animation:rise .3s ease-out}\n.score-header{height:90px;background:var(--acid);color:var(--ink);display:flex;align-items:center;padding:0 30px;font:600 .67rem DM Mono;letter-spacing:.13em}\n.score-header strong{margin-left:auto;font:800 2.6rem Manrope;letter-spacing:-.07em}\n.score-header small{align-self:center;margin:12px 0 0 4px}\n.score-grid{display:grid;grid-template-columns:repeat(5,1fr);border:1px solid var(--line);border-top:0}\n.metric{padding:22px;border-right:1px solid var(--line)}\n.metric:last-child{border:0}\n.metric span{display:block;font:500 .59rem DM Mono;color:var(--muted);letter-spacing:.12em;margin-bottom:8px}\n.metric strong{font-size:1.3rem}.metric i{display:block;height:3px;background:#344354;margin-top:12px}.metric i b{display:block;height:100%;background:var(--accent)}\n.diagnosis{display:grid;grid-template-columns:.8fr 1.6fr;border:1px solid var(--line);border-top:0}\n.diagnosis>div{padding:28px}\n.diagnosis>div:first-child{border-right:1px solid var(--line)}\n.diagnosis ol{padding-left:18px;margin:20px 0 0;color:#bec7ce;font-size:.87rem;line-height:1.55}\n.diagnosis li{margin-bottom:12px;padding-left:6px}\n.upgrade-stack{display:grid;gap:10px}\n.upgrade-stack article,.comparison-grid article,.analogy-feedback article{background:#101b27;border:1px solid var(--line);padding:17px 19px}\n.upgrade-stack article.local,.comparison-grid article.local,.analogy-feedback article.local{border-color:var(--accent)}\n.upgrade-stack span,.comparison-grid span,.analogy-feedback span{font:500 .59rem DM Mono;color:var(--muted);letter-spacing:.13em}\n.upgrade-stack article.local span,.comparison-grid article.local span,.analogy-feedback article.local span{color:var(--accent)}\n.upgrade-stack p,.comparison-grid p,.analogy-feedback p{margin:8px 0 0;font-size:.89rem;line-height:1.5}\n.coach-header{height:72px;background:var(--acid);color:var(--ink);display:flex;align-items:center;justify-content:space-between;padding:0 26px;font:700 .67rem DM Mono;letter-spacing:.13em}\n.listen-button.light{padding:10px;color:var(--ink)}\n.listen-button.light span{color:var(--ink)}\n.coach-feedback{display:grid;grid-template-columns:1fr 1fr 1.35fr;gap:10px;margin-top:10px}\n.coach-feedback article{background:#101b27;border:1px solid var(--line);padding:22px;min-height:160px}\n.coach-feedback article.local{border-color:var(--accent)}\n.coach-feedback article.praise{border-color:#758f36}\n.coach-feedback span{font:500 .59rem DM Mono;color:var(--muted);letter-spacing:.13em}\n.coach-feedback article.local span{color:var(--accent)}\n.coach-feedback article.praise span{color:var(--acid)}\n.coach-feedback p{margin:12px 0 0;font-size:.9rem;line-height:1.55}\n.rewrite-card p{font-size:clamp(1.4rem,3vw,2.3rem);line-height:1.35;max-width:800px;margin:28px 0 5px;font-weight:650;letter-spacing:-.035em}\n.rewrite-input{margin-top:0;padding:30px}\n.rewrite-tools{display:flex;align-items:center;justify-content:space-between}\n.rewrite-tools>span{font:500 .62rem DM Mono;color:var(--muted);letter-spacing:.1em}\n.comparison-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px}\n.comparison-grid article{min-height:145px}\n.analogy-stage{display:grid;grid-template-columns:1.3fr 1fr .65fr;background:var(--paper);color:var(--ink)}\n.constraint{padding:30px;border-right:1px solid #c7ced2}\n.constraint:last-child{border:0}.constraint.accent{background:var(--accent)}\n.constraint span{font:500 .6rem DM Mono;color:#6c7780;letter-spacing:.13em}\n.constraint h2{font-size:1.1rem;line-height:1.35;margin:18px 0 0;letter-spacing:-.02em}\n.analogy-response{border-top:0}\n.analogy-feedback{display:grid;grid-template-columns:1fr 1.5fr;gap:10px;margin-top:10px}\n.toast{position:fixed;bottom:24px;right:24px;max-width:340px;padding:13px 16px;background:var(--paper);color:var(--ink);font-size:.76rem;font-weight:650;transform:translateY(30px);opacity:0;pointer-events:none;transition:.25s;z-index:9}\n.toast.show{transform:none;opacity:1}\n@media(max-width:800px){\n  .shell{display:block}.rail{position:static;width:100%;height:auto;padding:18px;border-right:0;border-bottom:1px solid var(--line)}.brand{padding:0 0 16px}.mode-nav{display:grid;grid-template-columns:repeat(3,1fr)}.nav-item{grid-template-columns:1fr;padding:11px 9px}.nav-item span{display:none}.nav-item b{font-size:.7rem}.rail-bottom{display:none}main{width:100%}.topbar{height:58px;padding:0 18px}.date{display:none}.status{margin-right:auto}.workspace{width:calc(100% - 28px);padding:32px 0 60px}.session-head{align-items:start}.scenario-card,.rewrite-card{padding:24px}.response-zone{grid-template-columns:1fr;gap:20px;padding:24px}.timer-wrap,.target{padding:0;text-align:center}.diagnosis,.comparison-grid,.analogy-feedback,.coach-feedback{grid-template-columns:1fr}.diagnosis>div:first-child{border-right:0;border-bottom:1px solid var(--line)}.score-grid{grid-template-columns:repeat(2,1fr)}.metric:nth-child(2n){border-right:0}.analogy-stage{grid-template-columns:1fr}.constraint{border-right:0;border-bottom:1px solid #c7ced2}.constraint:last-child{border-bottom:0}h1{font-size:2.6rem}.scenario-meta{gap:10px}.rewrite-tools{align-items:end}.primary{font-size:.62rem}.chat-line{max-width:92%}.coach-header{height:auto;min-height:72px;gap:8px;padding:14px}.listen-button.light{text-align:right}\n}\n@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}\n</style>\n</head>\n<body>\n  <div class=\"shell\">\n    <aside class=\"rail\" aria-label=\"App navigation\">\n      <div class=\"brand\">\n        <div class=\"brand-mark\">AM</div>\n        <div><strong>JACK</strong><span>AMERICAN MODE</span></div>\n      </div>\n\n      <nav class=\"mode-nav\" aria-label=\"Training modes\">\n        <button class=\"nav-item active\" data-mode=\"pressure\"><span>01</span><b>Live Native<br/>Coach</b></button>\n        <button class=\"nav-item\" data-mode=\"upgrade\"><span>02</span><b>Make It<br/>American</b></button>\n        <button class=\"nav-item\" data-mode=\"analogy\"><span>03</span><b>Coach My<br/>English</b></button>\n      </nav>\n\n      <div class=\"rail-bottom\">\n        <div class=\"streak\"><span class=\"streak-num\" id=\"streakValue\">4</span><span>DAY<br/>STREAK</span></div>\n        <div class=\"level\"><span>FIELD LEVEL</span><strong>C1 → C2</strong><div class=\"level-track\"><i></i></div></div>\n      </div>\n    </aside>\n\n    <main>\n      <header class=\"topbar\">\n        <div class=\"status\"><i></i> LIVE TRAINING</div>\n        <div class=\"date\" id=\"today\"></div>\n        <button class=\"icon-button\" id=\"soundToggle\" aria-label=\"Toggle prompt audio\">SOUND ON</button>\n      </header>\n\n      <section class=\"workspace active\" id=\"pressurePanel\">\n        <div class=\"session-head\">\n          <div><span class=\"eyebrow\">LIVE ROLEPLAY · THREE TURNS</span><h1>Talk. Get pushed.</h1></div>\n          <div class=\"session-count\"><strong id=\"drillIndex\">01</strong><span>/ 04</span></div>\n        </div>\n\n        <div class=\"scenario-card\">\n          <div class=\"scenario-meta\">\n            <span id=\"scenarioContext\">WORK · FINANCE</span>\n            <span class=\"difficulty\" id=\"turnCounter\">TURN 1 OF 3</span>\n          </div>\n          <p class=\"role\" id=\"scenarioRole\">Your CFO interrupts your update:</p>\n          <blockquote id=\"scenarioPrompt\">“I still don't understand why this number moved. Give me the short version.”</blockquote>\n          <button class=\"listen-button\" id=\"listenPressure\" aria-label=\"Listen to coach\"><span>▶</span> HEAR YOUR COACH</button>\n        </div>\n\n        <div class=\"conversation-log\" id=\"conversationLog\" aria-live=\"polite\"></div>\n\n        <div class=\"response-zone\">\n          <div class=\"timer-wrap\"><span class=\"timer\" id=\"pressureTimer\">00:00</span><span>RESPONSE TIME</span></div>\n          <div class=\"record-core\">\n            <button class=\"record-button\" id=\"pressureRecord\" aria-label=\"Start speaking\"><span></span></button>\n            <strong id=\"pressureAction\">ANSWER YOUR COACH</strong>\n            <small>Your coach responds after every turn.</small>\n          </div>\n          <div class=\"target\"><span>COACH</span><strong>VOICE ON</strong></div>\n        </div>\n\n        <div class=\"transcript-wrap hidden\" id=\"pressureTranscriptWrap\">\n          <label for=\"pressureTranscript\">YOUR LIVE TRANSCRIPT</label>\n          <textarea id=\"pressureTranscript\" placeholder=\"Your transcript appears here. You can also type when voice recognition is unavailable.\"></textarea>\n          <button class=\"primary\" id=\"analyzePressure\">SEND TO COACH <span>→</span></button>\n        </div>\n\n        <section class=\"results hidden\" id=\"pressureResults\" aria-live=\"polite\">\n          <div class=\"coach-header\"><span>NATIVE COACHING</span><button class=\"listen-button light\" id=\"replayPressure\"><span>▶</span> HEAR FEEDBACK AGAIN</button></div>\n          <div class=\"coach-feedback\">\n            <article class=\"praise\"><span>WHAT SOUNDED GOOD</span><p id=\"pressurePraise\"></p></article>\n            <article><span>ONE REAL CORRECTION</span><p id=\"pressureCorrection\"></p></article>\n            <article class=\"local\"><span>NATIVE REPLAY</span><p id=\"localVersion\"></p></article>\n          </div>\n          <button class=\"primary wide\" id=\"nextPressure\">START A NEW CONVERSATION <span>→</span></button>\n        </section>\n      </section>\n\n      <section class=\"workspace\" id=\"upgradePanel\">\n        <div class=\"session-head\">\n          <div><span class=\"eyebrow\">REWRITE UNDER PRESSURE</span><h1>Lose the textbook.</h1></div>\n          <div class=\"session-count\"><strong id=\"upgradeIndex\">01</strong><span>/ 04</span></div>\n        </div>\n        <div class=\"rewrite-card\">\n          <span class=\"card-label\">TOO CORRECT TO SOUND REAL</span>\n          <p id=\"stiffSentence\">“I was very surprised because the result was completely different from my expectation.”</p>\n          <button class=\"listen-button\" id=\"listenUpgrade\"><span>▶</span> HEAR THE LINE</button>\n        </div>\n        <div class=\"rewrite-input\">\n          <label for=\"upgradeText\">SAY IT LIKE YOU LIVE HERE</label>\n          <textarea id=\"upgradeText\" placeholder=\"Your version. Shorter is usually better.\"></textarea>\n          <div class=\"rewrite-tools\"><span id=\"wordCount\">0 WORDS</span><button class=\"primary\" id=\"compareUpgrade\">COMPARE VERSIONS <span>→</span></button></div>\n        </div>\n        <section class=\"results hidden\" id=\"upgradeResults\" aria-live=\"polite\">\n          <div class=\"comparison-grid\">\n            <article><span>YOUR VERSION</span><p id=\"yourUpgrade\"></p></article>\n            <article class=\"local\"><span>LOCAL</span><p id=\"modelUpgrade\"></p></article>\n            <article><span>WHY IT LANDS</span><p id=\"upgradeWhy\"></p></article>\n          </div>\n          <button class=\"primary wide\" id=\"nextUpgrade\">NEXT REWRITE <span>→</span></button>\n        </section>\n      </section>\n\n      <section class=\"workspace\" id=\"analogyPanel\">\n        <div class=\"session-head\">\n          <div><span class=\"eyebrow\">PERSONAL SPEAKING REVIEW</span><h1>Let a native coach in.</h1></div>\n          <div class=\"session-count\"><strong id=\"analogyIndex\">01</strong><span>/ 04</span></div>\n        </div>\n        <div class=\"analogy-stage\">\n          <div class=\"constraint\"><span>YOUR COACH ASKS</span><h2 id=\"analogyTopic\">Tell me about a recent moment when you changed your mind.</h2></div>\n          <div class=\"constraint\"><span>FOCUS</span><h2 id=\"analogyAudience\">Natural flow, not perfect grammar</h2></div>\n          <div class=\"constraint accent\"><span>TIME</span><h2 id=\"analogyTime\">45–60 seconds</h2></div>\n        </div>\n        <button class=\"listen-button prompt-audio\" id=\"listenAnalogy\"><span>▶</span> HEAR THE QUESTION</button>\n        <div class=\"response-zone analogy-response\">\n          <div class=\"timer-wrap\"><span class=\"timer\" id=\"analogyTimer\">00:00</span><span>RESPONSE TIME</span></div>\n          <div class=\"record-core\">\n            <button class=\"record-button\" id=\"analogyRecord\" aria-label=\"Start analogy\"><span></span></button>\n            <strong id=\"analogyAction\">TALK TO YOUR COACH</strong>\n            <small>Speak naturally. Corrections come afterward.</small>\n          </div>\n          <div class=\"target\"><span>STYLE</span><strong>BE YOURSELF</strong></div>\n        </div>\n        <div class=\"transcript-wrap hidden\" id=\"analogyTranscriptWrap\">\n          <label for=\"analogyTranscript\">YOUR LIVE TRANSCRIPT</label>\n          <textarea id=\"analogyTranscript\" placeholder=\"Your transcript appears here.\"></textarea>\n          <button class=\"primary\" id=\"analyzeAnalogy\">ASK THE COACH <span>→</span></button>\n        </div>\n        <section class=\"results hidden\" id=\"analogyResults\" aria-live=\"polite\">\n          <div class=\"coach-header\"><span>SPOKEN FEEDBACK</span><button class=\"listen-button light\" id=\"replayAnalogy\"><span>▶</span> HEAR FEEDBACK AGAIN</button></div>\n          <div class=\"coach-feedback\">\n            <article class=\"praise\"><span>GIVE YOURSELF CREDIT</span><p id=\"analogyWorked\"></p></article>\n            <article><span>ONE UPGRADE</span><p id=\"analogyCorrection\"></p></article>\n            <article class=\"local\"><span>HOW I’D SAY IT</span><p id=\"analogyModel\"></p></article>\n          </div>\n          <button class=\"primary wide\" id=\"nextAnalogy\">NEXT COACHING QUESTION <span>→</span></button>\n        </section>\n      </section>\n    </main>\n  </div>\n\n  <div class=\"toast\" id=\"toast\" role=\"status\"></div>\n  <script>const conversations = [\n  {\n    context:'WORK · FINANCE', role:'Your CFO interrupts your update:',\n    prompt:'I still don’t understand why this number moved. Give me the short version.',\n    followups:['Okay, but what should I tell the regional team?','And what are you going to do so this doesn’t happen again next month?'],\n    local:'It’s basically a timing issue. The cost hit this month, while the sales showed up last month. I’ll flag it in the regional update and tighten the cutoff check next month.'\n  },\n  {\n    context:'SOCIAL · DINNER', role:'A friend notices you barely touched the food:',\n    prompt:'You good? You’ve been moving that steak around for ten minutes.',\n    followups:['Come on, is it the food or is something else going on?','All right, then tell me one good thing that happened this week.'],\n    local:'I’m good—I just ate way too late, so I’m still kind of full. The steak’s innocent. Actually, one good thing did happen this week.'\n  },\n  {\n    context:'YOUTUBE · CREATIVE', role:'Your editor pushes back on your opening:',\n    prompt:'This intro is accurate, but why would anyone keep watching?',\n    followups:['So what’s the tension? Give me the hook in one sentence.','Better. Now tell me what you’d cut from the first thirty seconds.'],\n    local:'That’s fair. It explains the topic, but it doesn’t give people a reason to care. The real hook is that advanced English can still sound translated. I’d cut the setup and get straight to that.'\n  },\n  {\n    context:'INVESTING · FRIENDS', role:'A friend challenges your Tesla position:',\n    prompt:'Be honest—are you investing, or are you just emotionally attached at this point?',\n    followups:['What would actually make you admit the thesis is wrong?','So if that happened tomorrow, would you really sell?'],\n    local:'Honestly, maybe a little of both. But the thesis isn’t untouchable. If execution breaks down and the long-term upside disappears, I’m out. Painfully, but I’m out.'\n  }\n];\n\nconst rewrites = [\n  {stiff:'“I was very surprised because the result was completely different from my expectation.”', local:'“That caught me completely off guard. I did not see it coming.”', why:'“Caught me off guard” packages surprise and mismatch into one natural chunk. The second sentence adds rhythm instead of explanation.'},\n  {stiff:'“I think we should discuss this matter again because there are several points which are not clear.”', local:'“We should circle back on this. A few things still aren’t clear.”', why:'Two short beats sound decisive. “Circle back” fits workplace speech, while “this matter” belongs in a legal notice.'},\n  {stiff:'“I could not understand why he became angry so suddenly.”', local:'“I couldn’t figure out why he blew up out of nowhere.”', why:'“Figure out,” “blew up,” and “out of nowhere” are high-frequency spoken chunks with a clear emotional picture.'},\n  {stiff:'“The meeting continued for a long time, although there was almost no meaningful discussion.”', local:'“The meeting dragged on, and somehow we still said nothing.”', why:'“Dragged on” carries the duration and frustration. “Somehow” adds a dry, conversational edge.'}\n];\n\nconst coachingQuestions = [\n  {question:'Tell me about a recent moment when you changed your mind.',focus:'Natural flow, not perfect grammar',time:'45–60 seconds',model:'I was pretty convinced at first, but the more I looked into it, the less the argument held up. Eventually I had to admit I’d been looking at it the wrong way.'},\n  {question:'Explain a frustrating work problem without sounding bitter.',focus:'Control the tone and land the point',time:'45–60 seconds',model:'The frustrating part wasn’t the extra work itself. It was that the expectations kept changing, so I was solving a different problem every ten minutes.'},\n  {question:'Describe why a YouTube idea failed—and make it interesting.',focus:'Story structure and a clean ending',time:'45–60 seconds',model:'The idea made sense on paper, which was the problem. It was useful, polished, and completely incapable of making anyone click. Basically, I made homework with a thumbnail.'},\n  {question:'Defend one investment belief without giving me a lecture.',focus:'Conviction, brevity, and personality',time:'45–60 seconds',model:'I’m not pretending the stock is safe. I just think the market is pricing the risk more clearly than the upside, and that gap is exactly why I’m still in.'}\n];\n\nconst $ = id => document.getElementById(id);\nlet pressureIndex=0, upgradeIndex=0, analogyIndex=0, pressureTurn=0;\nlet soundOn=true, activeTimer=null, elapsed=0, recognition=null;\nlet conversationText=[], lastPressureFeedback='', lastAnalogyFeedback='';\n\nfunction loadStreak(){\n  const state=JSON.parse(localStorage.getItem('americanModeProgress')||'{\"streak\":0}');\n  $('streakValue').textContent=state.streak||0;\n}\nfunction markPractice(){\n  const today=new Date().toISOString().slice(0,10);\n  const state=JSON.parse(localStorage.getItem('americanModeProgress')||'{\"streak\":0,\"last\":\"\"}');\n  if(state.last!==today){const prior=new Date(Date.now()-86400000).toISOString().slice(0,10);state.streak=state.last===prior?(state.streak||0)+1:1;state.last=today;localStorage.setItem('americanModeProgress',JSON.stringify(state));$('streakValue').textContent=state.streak;}\n}\nfunction formatDate(){$('today').textContent=new Intl.DateTimeFormat('en-US',{weekday:'short',month:'short',day:'numeric'}).format(new Date()).toUpperCase();}\n\nfunction chooseVoice(){\n  const voices=speechSynthesis.getVoices();\n  return voices.find(v=>/Samantha|Ava|Allison|Evan|Nathan|Aaron/i.test(v.name)&&/^en-US/i.test(v.lang))||voices.find(v=>/^en-US/i.test(v.lang));\n}\nfunction speak(text){\n  if(!soundOn||!('speechSynthesis' in window))return;\n  speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text.replace(/[“”]/g,''));u.lang='en-US';u.rate=.98;u.pitch=.96;const voice=chooseVoice();if(voice)u.voice=voice;speechSynthesis.speak(u);\n}\nfunction toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600);}\nfunction setMode(mode){document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));document.querySelectorAll('.workspace').forEach(p=>p.classList.remove('active'));$(`${mode}Panel`).classList.add('active');speechSynthesis?.cancel();}\ndocument.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));\n$('soundToggle').addEventListener('click',()=>{soundOn=!soundOn;$('soundToggle').textContent=soundOn?'SOUND ON':'SOUND OFF';});\n\nfunction startTimer(display){clearInterval(activeTimer);elapsed=0;display.textContent='00:00';activeTimer=setInterval(()=>{elapsed++;display.textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(elapsed%60).padStart(2,'0')}`;},1000);}\nfunction stopTimer(){clearInterval(activeTimer);activeTimer=null;}\nfunction startRecognition(textarea,button,action,wrap,timer){\n  const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;\n  if(!SpeechRecognition){wrap.classList.remove('hidden');textarea.focus();toast('Voice recognition is unavailable here. Type your response instead.');return;}\n  if(button.classList.contains('recording')){recognition?.stop();return;}\n  speechSynthesis?.cancel();recognition=new SpeechRecognition();recognition.lang='en-US';recognition.interimResults=true;recognition.continuous=true;let finalText='';\n  recognition.onstart=()=>{button.classList.add('recording');action.textContent='I’M LISTENING';wrap.classList.remove('hidden');startTimer(timer);};\n  recognition.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){if(e.results[i].isFinal)finalText+=e.results[i][0].transcript+' ';else interim+=e.results[i][0].transcript;}textarea.value=(finalText+interim).trim();};\n  recognition.onend=()=>{button.classList.remove('recording');action.textContent='RECORD AGAIN';stopTimer();};\n  recognition.onerror=()=>{button.classList.remove('recording');action.textContent='TYPE YOUR RESPONSE';wrap.classList.remove('hidden');stopTimer();toast('I missed that. Type it or try the mic again.');};\n  recognition.start();\n}\n\nfunction correctionFor(text){\n  const rules=[\n    [/make(s|) it cleared/i,'Say “make it clearer,” not “make it cleared.” Clearer describes the result you want.'],\n    [/more clear/i,'Use “clearer” instead of “more clear.” It is shorter and more natural.'],\n    [/discuss about/i,'Say “discuss it,” not “discuss about it.” Discuss already carries the idea of “about.”'],\n    [/explain me/i,'Say “explain it to me.” The person comes after “to.”'],\n    [/according to me/i,'Use “in my view” or just “I think.” “According to me” sounds translated.'],\n    [/I agree with your opinion/i,'Simply say “I agree.” The rest is understood.'],\n    [/could understand/i,'If you mean you successfully understood it, say “I understood” or “I was able to understand.”'],\n    [/different (than|from) my expectation/i,'In conversation, “not what I expected” sounds more natural than “different from my expectation.”'],\n    [/due to the fact that/i,'Replace “due to the fact that” with “because.” Four words just resigned.'],\n    [/in order to/i,'Most of the time, “to” does the same job as “in order to” and sounds lighter.']\n  ];\n  for(const [pattern,message] of rules)if(pattern.test(text))return message;\n  const fillers=(text.match(/\\b(um|uh|you know|I mean|like)\\b/gi)||[]).length;\n  if(fillers>=4)return `You used ${fillers} filler phrases. Keep one or two—they sound human—but replace the rest with a short pause.`;\n  if(/\\b(regarding|moreover|therefore|nevertheless|this matter)\\b/i.test(text))return 'Your grammar works, but a few written-English words make the delivery feel formal. Use shorter spoken connectors such as “but,” “so,” or “the thing is.”';\n  if(!/\\b\\w+'(t|m|re|ve|ll|d|s)\\b/i.test(text)&&/\\b(I am|I have|I will|do not|did not|cannot|it is|that is)\\b/i.test(text))return 'Use contractions when the tone is conversational. “I’m,” “I’ve,” and “that’s” will immediately loosen the rhythm.';\n  return 'Your meaning was clear. The next upgrade is compression: lead with the answer, keep one supporting detail, and stop before you explain the same idea twice.';\n}\nfunction praiseFor(text){\n  const words=text.trim().split(/\\s+/).filter(Boolean).length;\n  const chunks=(text.match(/\\b(kind of|pretty much|turns out|at this point|the thing is|fair enough|honestly|I mean|I’m good|caught me off guard)\\b/gi)||[]).length;\n  if(words>=35&&chunks>=1)return 'That sounded fluent and lived-in. You developed the point without losing the thread, and your conversational chunks helped the rhythm feel American rather than translated.';\n  if(words>=22)return 'You gave a complete answer and kept the logic easy to follow. More importantly, you sounded comfortable—not like you were assembling grammar in real time.';\n  if(words>=12)return 'Your answer was direct and easy to understand. That instinct to get to the point is already one of your strongest native-like habits.';\n  return 'The response was clear and decisive. You did not hide behind unnecessary vocabulary, which is exactly what natural spoken English needs.';\n}\nfunction cleanReplay(text){\n  let out=text.trim()\n    .replace(/\\b(um+|uh+)\\b[,.]?\\s*/gi,'')\n    .replace(/\\byou know\\b[,.]?\\s*/gi,'')\n    .replace(/\\bI think that\\b/gi,'I think')\n    .replace(/make(s|) it cleared/gi,'make$1 it clearer')\n    .replace(/more clear/gi,'clearer')\n    .replace(/discuss about/gi,'discuss')\n    .replace(/due to the fact that/gi,'because')\n    .replace(/in order to/gi,'to')\n    .replace(/different (than|from) my expectation/gi,'not what I expected')\n    .replace(/\\bI am\\b/g,'I’m').replace(/\\bI have\\b/g,'I’ve').replace(/\\bI will\\b/g,'I’ll').replace(/\\bdo not\\b/g,'don’t').replace(/\\bdid not\\b/g,'didn’t').replace(/\\bit is\\b/g,'it’s').replace(/\\bthat is\\b/g,'that’s')\n    .replace(/\\s{2,}/g,' ').trim();\n  if(!out)return '';\n  out=out.charAt(0).toUpperCase()+out.slice(1);\n  if(!/[.!?]$/.test(out))out+='.';\n  return out;\n}\nfunction spokenFeedback(praise,correction,replay){return `Here’s the honest version. ${praise} One upgrade: ${correction} A more natural replay would be: ${replay}`;}\nasync function askClaude(transcript,mode,context){\n  const response=await fetch('/api/coach',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({transcript,mode,context})});\n  const data=await response.json().catch(()=>({}));\n  if(!response.ok)throw new Error(data.error||'Claude coaching is unavailable.');\n  document.querySelector('.status').innerHTML='<i></i> CLAUDE ACTIVE';\n  return data;\n}\nasync function checkClaude(){\n  try{const response=await fetch('/api/health');const data=await response.json();document.querySelector('.status').innerHTML=`<i></i> ${data.configured?'CLAUDE READY':'CLAUDE NOT CONFIGURED'}`;}\n  catch{document.querySelector('.status').innerHTML='<i></i> COACH OFFLINE';}\n}\nfunction addChat(who,text){const line=document.createElement('div');line.className=`chat-line ${who==='COACH'?'coach':'you'}`;const label=document.createElement('span');label.textContent=who;const body=document.createElement('div');body.textContent=text;line.append(label,body);$('conversationLog').appendChild(line);}\n\nfunction loadPressure(){\n  const d=conversations[pressureIndex];pressureTurn=0;conversationText=[];$('drillIndex').textContent=String(pressureIndex+1).padStart(2,'0');$('scenarioContext').textContent=d.context;$('scenarioRole').textContent=d.role;$('scenarioPrompt').textContent=`“${d.prompt}”`;$('turnCounter').textContent='TURN 1 OF 3';$('conversationLog').innerHTML='';$('pressureTranscript').value='';$('pressureTranscriptWrap').classList.add('hidden');$('pressureResults').classList.add('hidden');$('pressureTimer').textContent='00:00';$('pressureAction').textContent='ANSWER YOUR COACH';window.scrollTo({top:0,behavior:'smooth'});\n}\n$('listenPressure').addEventListener('click',()=>speak(pressureTurn===0?conversations[pressureIndex].prompt:conversations[pressureIndex].followups[pressureTurn-1]));\n$('pressureRecord').addEventListener('click',()=>startRecognition($('pressureTranscript'),$('pressureRecord'),$('pressureAction'),$('pressureTranscriptWrap'),$('pressureTimer')));\n$('analyzePressure').addEventListener('click',async()=>{\n  const text=$('pressureTranscript').value.trim();if(text.split(/\\s+/).length<4){toast('Give your coach a real answer. Four words is a getaway attempt.');return;}\n  recognition?.stop();stopTimer();addChat('YOU',text);conversationText.push(text);pressureTurn++;\n  if(pressureTurn<3){const followup=conversations[pressureIndex].followups[pressureTurn-1];addChat('COACH',followup);$('scenarioRole').textContent='Your coach follows up:';$('scenarioPrompt').textContent=`“${followup}”`;$('turnCounter').textContent=`TURN ${pressureTurn+1} OF 3`;$('pressureTranscript').value='';$('pressureTranscriptWrap').classList.add('hidden');$('pressureAction').textContent='ANSWER THE FOLLOW-UP';speak(followup);return;}\n  const all=conversationText.join(' ');let praise,correction,replay;\n  $('analyzePressure').disabled=true;$('analyzePressure').textContent='CLAUDE IS LISTENING…';\n  try{const result=await askClaude(all,'live_roleplay',{scenario:conversations[pressureIndex],turns:conversationText});praise=result.praise;correction=`${result.correction} ${result.why||''}`.trim();replay=result.local_version;}\n  catch(error){praise=praiseFor(all);correction=correctionFor(all);replay=conversations[pressureIndex].local;toast(`${error.message} Using local coaching instead.`);}\n  finally{$('analyzePressure').disabled=false;$('analyzePressure').innerHTML='SEND TO COACH <span>→</span>';}\n  $('pressurePraise').textContent=praise;$('pressureCorrection').textContent=correction;$('localVersion').textContent=replay;lastPressureFeedback=spokenFeedback(praise,correction,replay);$('pressureResults').classList.remove('hidden');markPractice();speak(lastPressureFeedback);$('pressureResults').scrollIntoView({behavior:'smooth',block:'start'});\n});\n$('replayPressure').addEventListener('click',()=>speak(lastPressureFeedback));\n$('nextPressure').addEventListener('click',()=>{pressureIndex=(pressureIndex+1)%conversations.length;loadPressure();});\n\nfunction loadUpgrade(){const d=rewrites[upgradeIndex];$('upgradeIndex').textContent=String(upgradeIndex+1).padStart(2,'0');$('stiffSentence').textContent=d.stiff;$('upgradeText').value='';$('wordCount').textContent='0 WORDS';$('upgradeResults').classList.add('hidden');window.scrollTo({top:0,behavior:'smooth'});}\n$('listenUpgrade').addEventListener('click',()=>speak(rewrites[upgradeIndex].stiff));\n$('upgradeText').addEventListener('input',e=>{$('wordCount').textContent=`${e.target.value.trim()?e.target.value.trim().split(/\\s+/).length:0} WORDS`;});\n$('compareUpgrade').addEventListener('click',()=>{const text=$('upgradeText').value.trim();if(text.split(/\\s+/).length<4){toast('Make the rewrite before checking the answer. Nice try.');return;}const d=rewrites[upgradeIndex];$('yourUpgrade').textContent=text;$('modelUpgrade').textContent=d.local;$('upgradeWhy').textContent=d.why;$('upgradeResults').classList.remove('hidden');markPractice();speak(`Good. Here is the local version. ${d.local} ${d.why}`);$('upgradeResults').scrollIntoView({behavior:'smooth',block:'start'});});\n$('nextUpgrade').addEventListener('click',()=>{upgradeIndex=(upgradeIndex+1)%rewrites.length;loadUpgrade();});\n\nfunction loadAnalogy(){const d=coachingQuestions[analogyIndex];$('analogyIndex').textContent=String(analogyIndex+1).padStart(2,'0');$('analogyTopic').textContent=d.question;$('analogyAudience').textContent=d.focus;$('analogyTime').textContent=d.time;$('analogyTranscript').value='';$('analogyTranscriptWrap').classList.add('hidden');$('analogyResults').classList.add('hidden');$('analogyTimer').textContent='00:00';$('analogyAction').textContent='TALK TO YOUR COACH';window.scrollTo({top:0,behavior:'smooth'});}\n$('listenAnalogy').addEventListener('click',()=>speak(coachingQuestions[analogyIndex].question));\n$('analogyRecord').addEventListener('click',()=>startRecognition($('analogyTranscript'),$('analogyRecord'),$('analogyAction'),$('analogyTranscriptWrap'),$('analogyTimer')));\n$('analyzeAnalogy').addEventListener('click',async()=>{\n  const text=$('analogyTranscript').value.trim();if(text.split(/\\s+/).length<7){toast('Give the coach enough English to coach. Keep going.');return;}recognition?.stop();stopTimer();let praise,correction,replay;\n  $('analyzeAnalogy').disabled=true;$('analyzeAnalogy').textContent='CLAUDE IS LISTENING…';\n  try{const result=await askClaude(text,'personal_review',coachingQuestions[analogyIndex]);praise=result.praise;correction=`${result.correction} ${result.why||''}`.trim();replay=result.local_version;}\n  catch(error){praise=praiseFor(text);correction=correctionFor(text);replay=cleanReplay(text);if(replay.toLowerCase()===text.toLowerCase()||replay.split(/\\s+/).length<8)replay=coachingQuestions[analogyIndex].model;toast(`${error.message} Using local coaching instead.`);}\n  finally{$('analyzeAnalogy').disabled=false;$('analyzeAnalogy').innerHTML='ASK THE COACH <span>→</span>';}\n  $('analogyWorked').textContent=praise;$('analogyCorrection').textContent=correction;$('analogyModel').textContent=replay;lastAnalogyFeedback=spokenFeedback(praise,correction,replay);$('analogyResults').classList.remove('hidden');markPractice();speak(lastAnalogyFeedback);$('analogyResults').scrollIntoView({behavior:'smooth',block:'start'});\n});\n$('replayAnalogy').addEventListener('click',()=>speak(lastAnalogyFeedback));\n$('nextAnalogy').addEventListener('click',()=>{analogyIndex=(analogyIndex+1)%coachingQuestions.length;loadAnalogy();});\n\nfunction registerAgentTools(){\n  const context=document.modelContext;if(!context?.registerTool)return;const modes=['pressure','upgrade','analogy'];\n  try{\n    context.registerTool({name:'open_training_mode',title:'Open training mode',description:'Open one of the three visible English training modes.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:modes}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!modes.includes(input?.mode))throw new Error('Unsupported training mode');setMode(input.mode);return{opened:input.mode};}});\n    context.registerTool({name:'read_current_drill',title:'Read current drill',description:'Read the active speaking prompt without changing progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){const mode=document.querySelector('.nav-item.active')?.dataset.mode;const prompt=mode==='pressure'?conversations[pressureIndex].prompt:mode==='upgrade'?rewrites[upgradeIndex].stiff:coachingQuestions[analogyIndex].question;return{mode,prompt};}});\n  }catch(error){console.warn('Agent tools unavailable',error);}\n}\n\nformatDate();loadStreak();loadPressure();loadUpgrade();loadAnalogy();registerAgentTools();checkClaude();\n</script>\n</body>\n</html>\n";
const voiceEnhancement=`
<script>
(()=>{
  let neuralVoiceReady=false,currentNeuralAudio=null,voiceRequest=0,latestSpokenFeedback='';
  const originalAskClaude=askClaude;
  function clearPlaying(){document.querySelectorAll('.listen-button.playing').forEach(button=>button.classList.remove('playing'));}
  function stopNeural(){voiceRequest++;if(currentNeuralAudio){currentNeuralAudio.pause();URL.revokeObjectURL(currentNeuralAudio.src);currentNeuralAudio=null;}clearPlaying();}
  function browserVoice(text,rate){
    if(!('speechSynthesis' in window))return;
    speechSynthesis.cancel();
    const utterance=new SpeechSynthesisUtterance(text.replace(/[“”]/g,''));
    utterance.lang='en-US';utterance.rate=rate*.98;utterance.pitch=.96;
    const voice=chooseVoice();if(voice)utterance.voice=voice;speechSynthesis.speak(utterance);
  }
  askClaude=async function(transcript,mode,context){const result=await originalAskClaude(transcript,mode,context);latestSpokenFeedback=result.spoken_feedback||'';return result;};
  spokenFeedback=function(praise,correction,replay){const natural=latestSpokenFeedback;latestSpokenFeedback='';return natural||('Yeah, that worked. '+praise+' I’d change one thing: '+correction+' Here’s how I’d say it: '+replay);};
  speak=async function(text,options){
    options=options||{};const rate=options.rate||1,button=options.button||null;
    if(!soundOn||!text)return;
    stopNeural();speechSynthesis?.cancel();const requestId=voiceRequest;
    if(button)button.classList.add('playing');
    if(neuralVoiceReady){
      try{
        const response=await fetch('/api/speech',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({text:text})});
        if(!response.ok)throw new Error('Neural voice unavailable');
        const blob=await response.blob();if(requestId!==voiceRequest)return;
        currentNeuralAudio=new Audio(URL.createObjectURL(blob));currentNeuralAudio.playbackRate=rate;currentNeuralAudio.preservesPitch=true;
        currentNeuralAudio.onended=()=>{button?.classList.remove('playing');if(currentNeuralAudio){URL.revokeObjectURL(currentNeuralAudio.src);currentNeuralAudio=null;}};
        currentNeuralAudio.onerror=()=>{button?.classList.remove('playing');};
        await currentNeuralAudio.play();return;
      }catch(error){neuralVoiceReady=false;}
    }
    button?.classList.remove('playing');browserVoice(text,rate);
  };
  function addReplayControls(header,replayId,slowId,textSource){
    if(!header||document.getElementById(replayId))return;
    const replay=document.createElement('button');replay.className='listen-button light';replay.id=replayId;replay.innerHTML='<span>▶</span> NATIVE REPLAY';
    const slow=document.createElement('button');slow.className='listen-button light';slow.id=slowId;slow.innerHTML='<span>◐</span> SHADOW 0.85×';
    replay.addEventListener('click',event=>speak(textSource(),{button:event.currentTarget}));
    slow.addEventListener('click',event=>speak(textSource(),{rate:.85,button:event.currentTarget}));
    header.append(replay,slow);
  }
  const pressureReplay=document.getElementById('replayPressure');if(pressureReplay)pressureReplay.innerHTML='<span>▶</span> COACH FEEDBACK';
  const analogyReplay=document.getElementById('replayAnalogy');if(analogyReplay)analogyReplay.innerHTML='<span>▶</span> COACH FEEDBACK';
  addReplayControls(pressureReplay?.parentElement,'playPressureNative','playPressureSlow',()=>document.getElementById('localVersion')?.textContent||'');
  addReplayControls(analogyReplay?.parentElement,'playAnalogyNative','playAnalogySlow',()=>document.getElementById('analogyModel')?.textContent||'');
  document.querySelectorAll('.nav-item,.record-button').forEach(button=>button.addEventListener('click',stopNeural,true));
  document.getElementById('soundToggle')?.addEventListener('click',()=>{if(!soundOn)stopNeural();});
  fetch('/api/health').then(response=>response.json()).then(data=>{neuralVoiceReady=Boolean(data.voiceConfigured);document.querySelector('.status').innerHTML='<i></i> '+(data.configured?(neuralVoiceReady?'CLAUDE + NEURAL VOICE':'CLAUDE READY'):'CLAUDE NOT CONFIGURED');}).catch(()=>{});
})();
</script>`;
