const realtimeEnhancement=`
<script type="module">
import { Conversation } from 'https://cdn.jsdelivr.net/npm/@elevenlabs/client@1.10.0/+esm';
const byId=id=>document.getElementById(id);
let liveConversation=null,micMuted=false,selectedTopic='open',selectedLabel='Open conversation',loadedMemory=null,sessionTurns=[],wakeLock=null;
let iosAudioPrimer=null,connectTimer=null;
const startButton=byId('startRealtime'),muteButton=byId('muteRealtime'),orb=byId('voiceOrb');
const isIosSafari=/iP(?:hone|ad|od)/.test(navigator.userAgent)&&/WebKit/.test(navigator.userAgent);
const iosKickstart='Start our conversation now with one short, friendly question.';
const lockTopics=locked=>document.querySelectorAll('.topic-chip').forEach(chip=>{chip.disabled=locked;});
function topicChip(topic,label){const button=document.createElement('button');button.type='button';button.className='topic-chip custom-topic';button.setAttribute('role','radio');button.setAttribute('aria-checked','false');button.dataset.topic=topic;button.dataset.label=label;button.textContent=label.toUpperCase();return button;}
async function loadCustomTopics(){
  try{const response=await fetch('/api/topics');const data=await response.json();if(!response.ok)return;const add=byId('addTopic');for(const topic of data.topics||[])if(!document.querySelector('[data-topic="'+CSS.escape(topic.key)+'"]'))byId('topicList').insertBefore(topicChip(topic.key,topic.label),add);}catch{}
}
function setLiveState(state,detail){
  byId('realtimeState').textContent=state;
  byId('realtimeSubstate').textContent=detail||'';
  const pill=byId('realtimePill');pill.querySelector('span').textContent=state;
  pill.classList.toggle('connected',state==='LISTENING'||state==='SPEAKING');
  orb.classList.toggle('listening',state==='LISTENING');orb.classList.toggle('speaking',state==='SPEAKING');
}
function addLine(source,text){
  if(!text||typeof text!=='string')return;
  if(source==='user'&&text.trim()===iosKickstart)return;
  sessionTurns.push({speaker:source==='user'?'Yuichi':'Jack',text:text.trim()});
  byId('emptyRealtimeLog')?.remove();
  const line=document.createElement('div');line.className='chat-line '+(source==='user'?'you':'coach');
  const label=document.createElement('span');label.textContent=source==='user'?'YOU':'JACK';
  const copy=document.createElement('p');copy.textContent=text;line.append(label,copy);byId('realtimeLog').append(line);
  line.scrollIntoView({behavior:'smooth',block:'nearest'});
}
function memoryText(memory){
  if(!memory)return 'No saved memory yet. This conversation will start it.';
  const pieces=[];
  if(memory.summary)pieces.push(memory.summary);
  if(Array.isArray(memory.open_threads)&&memory.open_threads.length)pieces.push('Continue: '+memory.open_threads.slice(0,2).join('; '));
  return pieces.join(' · ').slice(0,300);
}
async function loadTopicMemory(){
  const status=byId('memoryStatus'),preview=byId('memoryPreview');status.textContent='CHECKING MEMORY…';preview.classList.add('hidden');
  try{
    const response=await fetch('/api/memory?topic='+encodeURIComponent(selectedTopic));const data=await response.json().catch(()=>({}));
    if(!response.ok)throw new Error(data.error||'Memory is unavailable.');loadedMemory=data.memory||null;
    status.textContent=loadedMemory?'MEMORY READY · '+String(data.sessionCount||1)+' SESSION'+(data.sessionCount===1?'':'S'):'NEW TOPIC';
    preview.textContent=memoryText(loadedMemory);preview.classList.remove('hidden');
  }catch{loadedMemory=null;status.textContent='MEMORY UNAVAILABLE';preview.textContent='Jack can still talk, but this topic may not be saved.';preview.classList.remove('hidden');}
}
async function saveTopicMemory(){
  const useful=sessionTurns.filter(turn=>turn.text&&turn.text.length>1);if(useful.length<2)return;
  const status=byId('memoryStatus');status.textContent='SAVING MEMORY…';
  try{
    const response=await fetch('/api/memory',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({topic:selectedTopic,label:selectedLabel,turns:useful.slice(-40)})});
    const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Memory could not be saved.');loadedMemory=data.memory||loadedMemory;status.textContent='MEMORY SAVED';
    const preview=byId('memoryPreview');preview.textContent=memoryText(loadedMemory);preview.classList.remove('hidden');
  }catch{status.textContent='MEMORY NOT SAVED';}
}
function messageParts(event){
  const source=event?.source||event?.role||event?.message?.source||'';
  const text=typeof event?.message==='string'?event.message:(event?.message?.message||event?.text||event?.transcript||'');
  return{source:/user/i.test(source)?'user':'agent',text};
}
async function stopConversation(){
  clearTimeout(connectTimer);connectTimer=null;
  const active=liveConversation;liveConversation=null;
  try{if(active)await active.endSession();}catch{}
  try{await wakeLock?.release();}catch{}wakeLock=null;
  try{await iosAudioPrimer?.close();}catch{}iosAudioPrimer=null;
  await saveTopicMemory();
  lockTopics(false);
  startButton.disabled=false;startButton.innerHTML='START CONVERSATION <span>→</span>';startButton.classList.remove('danger');
  muteButton.classList.add('hidden');micMuted=false;setLiveState('READY','Tap once, then just talk.');
}
function primeIosAudio(){
  if(!isIosSafari)return;
  try{
    const AudioContextClass=window.AudioContext||window.webkitAudioContext;if(!AudioContextClass)return;
    iosAudioPrimer=new AudioContextClass();void iosAudioPrimer.resume();
    const oscillator=iosAudioPrimer.createOscillator(),gain=iosAudioPrimer.createGain();gain.gain.value=0.00001;
    oscillator.connect(gain).connect(iosAudioPrimer.destination);oscillator.start();oscillator.stop(iosAudioPrimer.currentTime+0.04);
  }catch{}
}
async function startConversation(){
  if(liveConversation){await stopConversation();return;}
  primeIosAudio();
  startButton.disabled=true;lockTopics(true);startButton.textContent='CONNECTING…';setLiveState('CONNECTING','Opening a private realtime voice session.');
  try{
    const permissionStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});permissionStream.getTracks().forEach(track=>track.stop());
    try{wakeLock=await navigator.wakeLock?.request('screen');}catch{}
    sessionTurns=[];
    const response=await fetch('/api/realtime-token',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({topic:selectedTopic,transport:'websocket'})});const data=await response.json().catch(()=>({}));
    if(!response.ok)throw new Error(data.error||'Realtime voice could not start.');
    if(!data.signedUrl)throw new Error('Jack did not receive a usable voice connection.');
    const sessionPromise=Conversation.startSession({
      signedUrl:data.signedUrl,connectionType:'websocket',dynamicVariables:{current_topic:selectedLabel,topic_memory:data.memoryText||'No earlier memory exists for this topic.'},
      onConnect:()=>{clearTimeout(connectTimer);connectTimer=null;startButton.disabled=false;startButton.textContent='END CONVERSATION';startButton.classList.add('danger');muteButton.classList.remove('hidden');setLiveState('LISTENING',isIosSafari?'Jack is waking up his iPhone voice…':'Jack is live. Speak naturally.');},
      onDisconnect:()=>{if(liveConversation)stopConversation();},
      onMessage:event=>{const message=messageParts(event);addLine(message.source,message.text);},
      onStatusChange:event=>{const status=typeof event==='string'?event:event?.status;if(status==='connecting')setLiveState('CONNECTING','Opening Jack’s voice channel.');},
      onModeChange:event=>{const mode=typeof event==='string'?event:event?.mode;if(mode==='speaking')setLiveState('SPEAKING','Jump in whenever you want—Jack can be interrupted.');else if(mode==='listening')setLiveState('LISTENING','Your turn.');else if(mode==='thinking'||mode==='processing')setLiveState('THINKING','Jack is forming a quick response.');},
      onError:error=>{console.error(error);const detail=error?.message||String(error||'Unknown connection error');setLiveState('CONNECTION ERROR','Tap Try Again.');byId('realtimeNote').textContent=detail;}
    });
    const timeoutPromise=new Promise((_,reject)=>{connectTimer=setTimeout(()=>reject(new Error('Jack could not establish the voice connection within 15 seconds.')),15000);});
    liveConversation=await Promise.race([sessionPromise,timeoutPromise]);
    if(isIosSafari&&liveConversation){
      setTimeout(()=>{if(liveConversation){liveConversation.sendUserMessage(iosKickstart);setLiveState('LISTENING','Jack is live. Speak naturally.');}},450);
    }
  }catch(error){
    clearTimeout(connectTimer);connectTimer=null;
    liveConversation=null;startButton.disabled=false;startButton.innerHTML='TRY AGAIN <span>→</span>';startButton.classList.remove('danger');
    lockTopics(false);
    setLiveState('COULD NOT CONNECT','Your regular coaching modes still work.');byId('realtimeNote').textContent=error.message;
  }
}
byId('topicList')?.addEventListener('click',async event=>{
  const button=event.target.closest('.topic-chip');if(!button||liveConversation)return;
  if(button.id==='addTopic'){byId('topicDialog').showModal();requestAnimationFrame(()=>byId('topicName').focus());return;}
  selectedTopic=button.dataset.topic;selectedLabel=button.dataset.label;
  document.querySelectorAll('.topic-chip:not(.add-topic)').forEach(chip=>{const active=chip===button;chip.classList.toggle('active',active);chip.setAttribute('aria-checked',String(active));});
  await loadTopicMemory();
});
byId('cancelTopic')?.addEventListener('click',()=>byId('topicDialog').close());
byId('topicForm')?.addEventListener('submit',async event=>{
  event.preventDefault();const input=byId('topicName'),label=input.value.trim();if(label.length<2)return;
  const submit=event.currentTarget.querySelector('[type="submit"]');submit.disabled=true;submit.textContent='CREATING…';
  try{const response=await fetch('/api/topics',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({label})});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Topic could not be created.');const button=topicChip(data.topic.key,data.topic.label);byId('topicList').insertBefore(button,byId('addTopic'));input.value='';byId('topicDialog').close();button.click();}
  catch(error){byId('memoryStatus').textContent=error.message.toUpperCase();}
  finally{submit.disabled=false;submit.textContent='CREATE TOPIC';}
});
startButton?.addEventListener('click',startConversation);
muteButton?.addEventListener('click',()=>{if(!liveConversation)return;micMuted=!micMuted;liveConversation.setMicMuted(micMuted);muteButton.textContent=micMuted?'UNMUTE MIC':'MUTE MIC';setLiveState(micMuted?'MIC MUTED':'LISTENING',micMuted?'Jack cannot hear you.':'Your turn.');});
document.querySelectorAll('.nav-item').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.mode!=='analogy'&&liveConversation)stopConversation();}));
document.addEventListener('visibilitychange',async()=>{if(document.visibilityState==='visible'&&liveConversation&&!wakeLock)try{wakeLock=await navigator.wakeLock?.request('screen');}catch{}});
loadCustomTopics();loadTopicMemory();
setLiveState('READY','Tap once, then just talk.');
</script>`;
